<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Schema Studio</title><style>
:root{--ink:#182238;--muted:#69748c;--line:#e4e9f2;--brand:#635bff;--canvas:#f6f8fc}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px/1.5 Inter,system-ui,sans-serif}.shell{max-width:1180px;margin:auto;padding:44px 24px 72px}.hero{display:flex;justify-content:space-between;gap:24px;margin-bottom:30px}.eyebrow{color:var(--brand);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.mark{display:inline-grid;place-items:center;width:26px;height:26px;border-radius:8px;background:linear-gradient(135deg,#756cff,#4d46dc);color:#fff;margin-right:8px;letter-spacing:0}h1{margin:10px 0 8px;font-size:clamp(30px,4vw,46px);line-height:1.1;letter-spacing:-.045em}.subtitle{max-width:620px;margin:0;color:var(--muted);font-size:17px}.save-note{height:max-content;margin-top:9px;padding:9px 13px;border:1px solid #dfe3ff;border-radius:99px;background:#f1f0ff;color:#514bb8;font-size:13px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:8px;margin-bottom:24px;border:1px solid var(--line);border-radius:16px;background:#fff}.step{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:11px;color:#8a93a8;font-size:14px;font-weight:700}.step span{display:grid;place-items:center;width:23px;height:23px;border:1px solid #ccd3e2;border-radius:50%;font-size:12px}.step.active{background:#f0efff;color:#423cc0}.step.active span{border-color:var(--brand);background:var(--brand);color:#fff}.card{padding:30px;border:1px solid var(--line);border-radius:20px;background:#fff;box-shadow:0 18px 50px #2d42600c}.panel{display:none}.panel.active{display:block}.section-heading{margin-bottom:25px}h2{margin:0;font-size:22px;letter-spacing:-.025em}.section-heading p,.box p{margin:5px 0 0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.span-2{grid-column:span 2}label{display:block;color:#35415b;font-size:13px;font-weight:700}input,select,textarea{width:100%;margin-top:7px;padding:11px 12px;border:1px solid #d5dbe7;border-radius:9px;outline:0;color:var(--ink);background:#fff;font:inherit}textarea{min-height:91px;resize:vertical}input:focus,select:focus,textarea:focus{border-color:#817bff;box-shadow:0 0 0 4px #635bff18}.muted{color:var(--muted);font-size:13px}.tip{display:flex;gap:10px;margin-top:24px;padding:14px 16px;border-radius:10px;background:#f7f8fc;color:#4f5b72;font-size:13px}.tip b{color:var(--brand)}.actions{display:flex;justify-content:space-between;gap:12px;margin-top:30px;padding-top:22px;border-top:1px solid var(--line)}button{border:0;border-radius:9px;padding:11px 17px;cursor:pointer;font:inherit;font-weight:800}.primary{background:var(--brand);color:#fff;box-shadow:0 8px 17px #635bff36}.text-button{padding-left:0;background:transparent;color:var(--brand)}.resource-bar{display:grid;grid-template-columns:1fr 210px;gap:18px;padding:17px;margin-bottom:22px;border-radius:12px;background:#f8f9fc}.table{overflow:auto;border:1px solid var(--line);border-radius:12px}.field-head,.field{display:grid;min-width:760px;grid-template-columns:1.45fr 1.1fr 96px 88px 1fr 38px;gap:10px;align-items:center;padding:11px 14px}.field-head{background:#f8f9fc;color:#7b869c;font-size:11px;font-weight:800;letter-spacing:.055em;text-transform:uppercase}.field{border-top:1px solid var(--line)}.field input,.field select{margin:0;padding:9px 10px}.check,.choice{display:flex;align-items:center;gap:7px}.field .check{font-size:13px}.check input,.choice input{width:auto;margin:0;accent-color:var(--brand)}.remove{width:30px;height:30px;padding:0;background:transparent;color:#a6afbe;font-size:20px}.add-field{margin-top:13px;border:1px dashed #aaa7ff;background:#f7f6ff;color:var(--brand)}.config{display:grid;grid-template-columns:1fr 1fr;gap:22px}.box{padding:19px;border:1px solid var(--line);border-radius:12px}.box h3{margin:0;font-size:15px}.box p{margin-bottom:13px;font-size:13px}.choice-row{display:flex;flex-wrap:wrap;gap:10px}.choice{margin:0;padding:10px 12px;border:1px solid #dce1eb;border-radius:9px;color:#46516a;cursor:pointer}.status{margin-bottom:20px;padding:13px 15px;border-radius:10px;background:#eaf8f3;color:#087a5b;font-weight:700}.error{display:block;margin-top:5px;color:#c0364e}@media(max-width:720px){.shell{padding:25px 15px 45px}.hero{display:block}.save-note{display:inline-block}.steps,.grid,.config,.resource-bar{grid-template-columns:1fr}.span-2{grid-column:auto}.card{padding:20px}}
</style></head><body><main class="shell"><header class="hero"><div><div class="eyebrow"><span class="mark">✦</span>Schema Studio</div><h1>Build your next resource with confidence.</h1><p class="subtitle">Set the project context once, then generate consistent database structure, permissions, translations and starter views.</p></div><div class="save-note">Project profile is saved locally</div></header><nav class="steps"><div class="step active" data-step="1"><span>1</span>Project workspace</div><div class="step" data-step="2"><span>2</span>Resource schema</div><div class="step" data-step="3"><span>3</span>Access & generate</div></nav>@if(session('status'))<div class="status">✓ {{ session('status') }}</div>@endif<form method="POST" action="{{ route('crud-generator.store') }}">@csrf
<section class="card panel active" data-panel="1"><div class="section-heading"><h2>Tell us about this project</h2><p>These defaults keep every generated resource aligned with your application.</p></div><div class="grid"><label>Project name<input name="project[name]" value="{{ old('project.name', $project['name'] ?? '') }}" placeholder="Acme Store" required>@error('project.name')<small class="error">{{ $message }}</small>@enderror</label><label>Primary language<select name="project[locale]" required><option value="en" @selected(old('project.locale', $project['locale'] ?? 'en') === 'en')>English</option><option value="ar" @selected(old('project.locale', $project['locale'] ?? 'en') === 'ar')>العربية</option></select></label><label class="span-2">What are you building?<textarea name="project[description]" placeholder="A short description to help your team recognize this workspace.">{{ old('project.description', $project['description'] ?? '') }}</textarea></label><label class="span-2">Default team roles<input name="project[roles]" value="{{ old('project.roles', $project['roles'] ?? 'admin, editor') }}" placeholder="admin, editor, support"><span class="muted">Used as the starting value whenever a resource needs permissions.</span></label></div><div class="tip"><b>✦</b><span>We save this profile in <code>storage/app/crud-schema-studio/project.json</code>. It is a small project manifest, not generated application code.</span></div><div class="actions"><span></span><button class="primary next" type="button">Continue to schema →</button></div></section>
<section class="card panel" data-panel="2"><div class="section-heading"><h2>Define the resource</h2><p>Start with the fields that describe a single record. You can always add more.</p></div><div class="resource-bar"><label>Resource / model name<input name="name" value="{{ old('name') }}" placeholder="Product" required>@error('name')<small class="error">{{ $message }}</small>@enderror</label><label>Table preview<input id="table-preview" value="products" readonly></label></div><div class="table"><div class="field-head"><span>Field name</span><span>Database type</span><span>Nullable</span><span>Unique</span><span>Default value</span><span></span></div><div id="fields"><div class="field"><input name="fields[0][name]" placeholder="name" required><select name="fields[0][type]"><option>string</option><option>text</option><option>integer</option><option>bigInteger</option><option>boolean</option><option>date</option><option>dateTime</option><option>decimal</option></select><label class="check"><input type="checkbox" name="fields[0][nullable]" value="1">Yes</label><label class="check"><input type="checkbox" name="fields[0][unique]" value="1">Yes</label><input name="fields[0][default]" placeholder="Optional"><button class="remove" type="button">×</button></div></div></div><button class="add-field" type="button" id="add">＋ Add another field</button><div class="actions"><button class="text-button back" type="button">← Back</button><button class="primary next" type="button">Configure access →</button></div></section>
<section class="card panel" data-panel="3"><div class="section-heading"><h2>Choose access and output</h2><p>Permissions are created only for the actions you enable.</p></div><div class="config"><div class="box"><h3>Translations</h3><p>Choose language files to create.</p><div class="choice-row"><label class="choice"><input type="checkbox" name="locales[]" value="en" checked>English</label><label class="choice"><input type="checkbox" name="locales[]" value="ar">العربية</label></div></div><div class="box"><h3>Permissions</h3><p>Assigned to each role below.</p><div class="choice-row"><label class="choice"><input type="checkbox" name="permissions[]" value="view" checked>View</label><label class="choice"><input type="checkbox" name="permissions[]" value="create" checked>Create</label><label class="choice"><input type="checkbox" name="permissions[]" value="update" checked>Update</label><label class="choice"><input type="checkbox" name="permissions[]" value="delete">Delete</label></div></div><div class="box"><h3>Roles for this resource</h3><p>Pre-filled from the project workspace.</p><label>Roles<input id="resource-roles" name="roles" value="{{ old('roles') }}" placeholder="admin, editor"></label></div><div class="box"><h3>Extra starter screen</h3><p>A simple dashboard showing this resource count.</p><label class="choice"><input type="checkbox" name="dashboard" value="1">Create dashboard</label></div></div><div class="actions"><button class="text-button back" type="button">← Back</button><button class="primary" type="submit">Generate CRUD →</button></div></section></form></main>
<template id="field"><div class="field"><input placeholder="field name" required><select><option>string</option><option>text</option><option>integer</option><option>bigInteger</option><option>boolean</option><option>date</option><option>dateTime</option><option>decimal</option></select><label class="check"><input type="checkbox" value="1">Yes</label><label class="check"><input type="checkbox" value="1">Yes</label><input placeholder="Optional"><button class="remove" type="button">×</button></div></template><script>let i=1,current=1;const panels=document.querySelectorAll('.panel'),steps=document.querySelectorAll('.step');function show(s){current=s;panels.forEach(p=>p.classList.toggle('active',+p.dataset.panel===s));steps.forEach(p=>p.classList.toggle('active',+p.dataset.step<=s));scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('.next').forEach(b=>b.onclick=()=>{if(current===1){const p=document.querySelector('[name="project[name]"]');if(!p.reportValidity())return;document.querySelector('#resource-roles').value=document.querySelector('[name="project[roles]"]').value;const locale=document.querySelector('[name="project[locale]"]').value;document.querySelectorAll('[name="locales[]"]').forEach(box=>box.checked=box.value===locale)}show(current+1)});document.querySelectorAll('.back').forEach(b=>b.onclick=()=>show(current-1));document.querySelector('#add').onclick=()=>{const n=document.querySelector('#field').content.cloneNode(true),e=n.querySelectorAll('input,select');e[0].name=`fields[${i}][name]`;e[1].name=`fields[${i}][type]`;e[2].name=`fields[${i}][nullable]`;e[3].name=`fields[${i}][unique]`;e[4].name=`fields[${i}][default]`;document.querySelector('#fields').append(n);i++};document.querySelector('#fields').onclick=e=>{if(e.target.closest('.remove')&&document.querySelectorAll('#fields .field').length>1)e.target.closest('.field').remove()};document.querySelector('[name="name"]').oninput=e=>{const n=e.target.value.trim().replace(/([a-z0-9])([A-Z])/g,'$1_$2').replace(/\s+/g,'_').toLowerCase();document.querySelector('#table-preview').value=n?(n.endsWith('s')?n:n+'s'):'products'};</script></body></html>
